DROP TABLE IF EXISTS `drivers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `drivers` (
  `_id` int NOT NULL AUTO_INCREMENT,
  `value` varchar(45) NOT NULL,
  `phone` varchar(18) DEFAULT NULL,
  `companyName` varchar(120) DEFAULT NULL,
  `TIN` varchar(12) DEFAULT NULL,
  `address` varchar(150) DEFAULT NULL,
  `currentAccount` varchar(150) DEFAULT NULL,
  `contract` varchar(10) DEFAULT NULL,
  `active` tinyint(1) DEFAULT '0',
  `addInfo` varchar(150) DEFAULT NULL,
  `KPP` varchar(10) DEFAULT NULL,
  `OGRN` varchar(15) DEFAULT NULL,
  `Acc` varchar(20) DEFAULT NULL,
  `CorAcc` varchar(20) DEFAULT NULL,
  `RCBIC` varchar(9) DEFAULT NULL,
  `bossName` varchar(90) DEFAULT NULL,
  `bankName` varchar(90) DEFAULT NULL,
  `bankAddress` varchar(200) DEFAULT NULL,
  PRIMARY KEY (`_id`),
  UNIQUE KEY `id_UNIQUE` (`_id`),
  UNIQUE KEY `value_UNIQUE` (`value`),
  UNIQUE KEY `TIN_UNIQUE` (`TIN`)
) ENGINE=InnoDB AUTO_INCREMENT=311 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

